using System;
using System.Collections.Generic;
using System.Threading;
using System.Security.Cryptography;
using System.IO;

namespace ImagePipeline
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 3;
        private DateTime _lastFailure = DateTime.MinValue;
        private readonly TimeSpan _timeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open)
                {
                    if (DateTime.UtcNow - _lastFailure > _timeout)
                    {
                        _state = CircuitState.HalfOpen;
                        return true;
                    }
                    return false;
                }
                return true;
            }
        }

        public void RecordSuccess()
        {
            lock (_lock) { _state = CircuitState.Closed; _failureCount = 0; }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailure = DateTime.UtcNow;
                if (_failureCount >= _threshold) _state = CircuitState.Open;
            }
        }
    }

    public class ResourcePool
    {
        private readonly Dictionary<string, long> _allocations = new Dictionary<string, long>();
        private long _totalCapacity = 1073741824; // 1GB
        private long _available;
        private readonly object _poolLock = new object();
        private readonly HashSet<string> _activeTransactions = new HashSet<string>();

        public ResourcePool() { _available = _totalCapacity; }

        public string Borrow(long amount, string transactionId = null)
        {
            lock (_poolLock)
            {
                if (amount > _available) return null;
                if (amount <= 0) return null;
                // Prevent re-entrant borrows during active flash transactions
                if (transactionId != null && _activeTransactions.Contains(transactionId))
                    return null;
                _available -= amount;
                string token = GenerateToken();
                _allocations[token] = amount;
                if (transactionId != null)
                    _activeTransactions.Add(transactionId);
                return token;
            }
        }

        public bool Return(string token, string transactionId = null)
        {
            lock (_poolLock)
            {
                if (!_allocations.ContainsKey(token)) return false;
                _available += _allocations[token];
                _allocations.Remove(token);
                if (transactionId != null)
                    _activeTransactions.Remove(transactionId);
                return true;
            }
        }

        public long GetBorrowed(string token)
        {
            lock (_poolLock)
            {
                return _allocations.ContainsKey(token) ? _allocations[token] : 0;
            }
        }

        public bool IsInTransaction(string transactionId)
        {
            lock (_poolLock) { return _activeTransactions.Contains(transactionId); }
        }

        public long Available => _available;

        private string GenerateToken()
        {
            byte[] bytes = new byte[16];
            using (var rng = RandomNumberGenerator.Create()) { rng.GetBytes(bytes); }
            return Convert.ToBase64String(bytes);
        }
    }

    public class ImageProcessingJob
    {
        public string JobId { get; set; }
        public byte[] ImageData { get; set; }
        public string OutputPath { get; set; }
        private int _width;
        private int _height;
        private bool _locked = false;

        public int Width
        {
            get => _width;
            set { if (!_locked) _width = value; }
        }

        public int Height
        {
            get => _height;
            set { if (!_locked) _height = value; }
        }

        public void LockDimensions() { _locked = true; }
        public void UnlockDimensions() { _locked = false; }
    }

    public class PipelineProcessor
    {
        private const int MaxDimension = 16384; // reasonable upper bound to avoid overflow / huge allocations

        private readonly CircuitBreaker _breaker = new CircuitBreaker();
        private readonly ResourcePool _pool = new ResourcePool();
        private readonly Dictionary<string, Action<ImageProcessingJob>> _callbacks = new Dictionary<string, Action<ImageProcessingJob>>();
        private readonly object _cbLock = new object();

        public void RegisterCallback(string phase, Action<ImageProcessingJob> callback)
        {
            lock (_cbLock) { _callbacks[phase] = callback; }
        }

        public bool ProcessImage(ImageProcessingJob job)
        {
            if (job == null)
            {
                return false;
            }

            // Unrelated fix: validate dimensions to prevent negative / overflow-prone sizing.
            if (job.Width <= 0 || job.Height <= 0 ||
                job.Width > MaxDimension || job.Height > MaxDimension)
            {
                Console.WriteLine("Invalid image dimensions");
                return false;
            }

            if (!_breaker.AllowRequest())
            {
                Console.WriteLine("Circuit open, rejecting request");
                return false;
            }

            try
            {
                long requiredMemory = (long)job.Width * job.Height * 4;
                string borrowToken = _pool.Borrow(requiredMemory);
                if (borrowToken == null)
                {
                    _breaker.RecordFailure();
                    return false;
                }

                try
                {
                    ExecutePhase("validate", job);
                    ExecutePhase("transform", job);

                    // Lock dimensions before flash allocation to prevent manipulation
                    job.LockDimensions();
                    long flashAmount = CalculateFlashAllocation(job);
                    string flashToken = _pool.Borrow(flashAmount, job.JobId);

                    try
                    {
                        ExecutePhase("render", job);
                        ExecutePhase("post_render", job);
                    }
                    finally
                    {
                        if (flashToken != null)
                        {
                            _pool.Return(flashToken, job.JobId);
                        }
                        job.UnlockDimensions();
                    }

                    ExecutePhase("finalize", job);
                    WriteOutput(job);
                    _breaker.RecordSuccess();
                    return true;
                }
                finally
                {
                    _pool.Return(borrowToken);
                }
            }
            catch (Exception ex)
            {
                _breaker.RecordFailure();
                Console.WriteLine($"Processing failed: {ex.Message}");
                return false;
            }
        }

        private long CalculateFlashAllocation(ImageProcessingJob job)
        {
            return (long)job.Width * job.Height * 2;
        }

        private void ExecutePhase(string phase, ImageProcessingJob job)
        {
            Action<ImageProcessingJob> callback;
            lock (_cbLock)
            {
                if (!_callbacks.TryGetValue(phase, out callback)) return;
            }
            callback(job);
        }

        private void WriteOutput(ImageProcessingJob job)
        {
            string safePath = Path.GetFullPath(job.OutputPath);
            string allowedDir = Path.GetFullPath("/var/output/images");
            if (!safePath.StartsWith(allowedDir + Path.DirectorySeparatorChar) && safePath != allowedDir)
                throw new UnauthorizedAccessException("Output path outside allowed directory");
            Console.WriteLine($"Writing {job.ImageData?.Length ?? 0} bytes to {safePath}");
        }
    }
}
